CREATE TABLE IF NOT EXISTS `#__xdecaroinventory_items` (`id` int unsigned NOT NULL AUTO_INCREMENT,`uuid` char(36) NOT NULL,`sku` varchar(100) DEFAULT NULL,`name` varchar(255) NOT NULL,`item_type` varchar(50) NOT NULL DEFAULT 'item',`quantity` decimal(14,3) NOT NULL DEFAULT 0,`unit` varchar(20) NOT NULL DEFAULT 'pcs',`state` tinyint NOT NULL DEFAULT 1,`access` int unsigned NOT NULL DEFAULT 1,`created` datetime NOT NULL,`created_by` int unsigned NOT NULL DEFAULT 0,`modified` datetime DEFAULT NULL,`modified_by` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY(`id`),UNIQUE KEY `idx_uuid`(`uuid`),UNIQUE KEY `idx_sku`(`sku`),KEY `idx_state_access`(`state`,`access`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__xdecaroinventory_movements` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`item_id` int unsigned NOT NULL,`quantity_delta` decimal(14,3) NOT NULL,`reason` varchar(100) NOT NULL,`note` varchar(500) DEFAULT NULL,`created` datetime NOT NULL,`created_by` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY(`id`),KEY `idx_item_created`(`item_id`,`created`),CONSTRAINT `fk_xdecaroinventory_movement_item` FOREIGN KEY (`item_id`) REFERENCES `#__xdecaroinventory_items`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
